/**
 * Monsters of the Game Master's Guide. Monsters don't use heroic actions or
 * reactions: they move (speed 6 unless noted), use what's on their stat
 * block and their turn is over. Saves: 1d20, unless noted.
 */
export type MonsterArmor = 'none' | 'M' | 'H';
export const MONSTER_ARMOR: Record<MonsterArmor, { name: string; text: string }> = {
  none: { name: 'Nessuna', text: 'Subisce i danni interi.' },
  M: { name: 'Media', text: 'Solo i dadi: ignora i modificatori ai danni (se non negativi).' },
  H: { name: 'Pesante', text: 'Metà dei dadi (per eccesso), ignorando i modificatori.' },
};

export interface MonsterAction {
  name: string;
  /** (2×): attacks twice */
  times?: number;
  /** damage formula, without the Primary Die flag */
  damage?: string;
  range?: number;
  reach?: number;
  text?: string;
}

export interface MonsterDef {
  id: string;
  name: string;
  en: string;
  group: string;
  /** «1/3», «2»… */
  level: string;
  size: 'tiny' | 'small' | 'medium' | 'large' | 'huge' | 'gargantuan';
  /** null: a minion (any damage kills it) */
  hp: number | null;
  armor: MonsterArmor;
  /** H*: armour that peels off (Heavy » Medium » None) */
  armorNote?: string;
  speed?: number;
  fly?: number;
  burrow?: number;
  minion?: boolean;
  flunky?: boolean;
  legendary?: boolean;
  /** legendary: saves with advantage/disadvantage, e.g. «FOR+ INT–» */
  saves?: string;
  traits: { name: string; text: string }[];
  /** legendary: «Dopo il turno di ogni eroe, scegli una:» */
  actionsNote?: string;
  actions: MonsterAction[];
  bloodied?: string;
  lastStand?: string;
}

