export const ALL_MONSTERS = [...MONSTERS, ...LEGENDARY];
export const getMonster = (id: string | null | undefined) => ALL_MONSTERS.find((m) => m.id === id);

/** monster level as a number (1/3 → 0.33) */
export const levelValue = (l: string) => (l.includes('/') ? Number(l.split('/')[0]) / Number(l.split('/')[1]) : Number(l));

/** Encounter difficulty: total monster levels against total hero levels. */
export function encounterDifficulty(heroLevels: number[], monsterLevels: number[]): { label: string; ratio: number } {
  const heroes = heroLevels.reduce((a, b) => a + b, 0);
  const monsters = monsterLevels.reduce((a, b) => a + b, 0);
  const ratio = heroes > 0 ? monsters / heroes : 0;
  const label = ratio === 0 ? '—' : ratio < 0.5 ? 'Facile' : ratio < 0.9 ? 'Media' : ratio <= 1.05 ? 'Difficile' : ratio < 1.5 ? 'Mortale' : 'Molto mortale';
  return { label, ratio };
}

